package io.ecosync.gateway;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
class JdbcSettingsTest {
 Map<String,Object> config(String type,boolean tls){return Map.of("databaseType",type,"host","approved.example","port",type.equals("MYSQL")?3306:5432,"databaseName","source","tls",tls,"username","reader","password","test-only-long-password");}
 @Test void mysqlDriverActuallyReceivesSecurityAndDeadlinePropertiesAsStrings(){var properties=Connections.settings(config("MYSQL",false)).getDataSourceProperties();var driver=new com.mysql.cj.conf.DefaultPropertySet();driver.initializeProperties(properties);assertThat(driver.getBooleanProperty(com.mysql.cj.conf.PropertyKey.allowPublicKeyRetrieval).getValue()).isTrue();assertThat(driver.getBooleanProperty(com.mysql.cj.conf.PropertyKey.allowMultiQueries).getValue()).isFalse();assertThat(driver.getBooleanProperty(com.mysql.cj.conf.PropertyKey.allowLoadLocalInfile).getValue()).isFalse();assertThat(driver.getIntegerProperty(com.mysql.cj.conf.PropertyKey.connectTimeout).getValue()).isEqualTo(3000);assertThat(driver.getIntegerProperty(com.mysql.cj.conf.PropertyKey.socketTimeout).getValue()).isEqualTo(5000);assertThat(properties.values()).allMatch(v->v instanceof String);}
 @Test void productionTlsCannotDowngradeAndPostgresDeadlineFlagsReachDriver(){var mysql=Connections.settings(config("MYSQL",true)).getDataSourceProperties();assertThat(mysql.getProperty("sslMode")).isEqualTo("VERIFY_IDENTITY");assertThat(mysql.getProperty("allowPublicKeyRetrieval")).isEqualTo("false");var pg=Connections.settings(config("POSTGRESQL",true)).getDataSourceProperties();assertThat(org.postgresql.PGProperty.SSL_MODE.get(pg)).isEqualTo("verify-full");assertThat(org.postgresql.PGProperty.CONNECT_TIMEOUT.get(pg)).isEqualTo("3");assertThat(org.postgresql.PGProperty.SOCKET_TIMEOUT.get(pg)).isEqualTo("5");assertThat(org.postgresql.PGProperty.OPTIONS.get(pg)).contains("statement_timeout=4000");}
}
